    "clementina.yaml": "format: clementina-project\nversion: 1\nname: Assembly Starter\ntarget:\n  machine: clementina-6502\nassets:\n  palettes: []\n  paletteConfigs: []\n  tilesets: []\n  backgrounds: []\n  overlays: []\n  shapes: []\n  animations: []\nbuild:\n  outputDirectory: build\n  assembly:\n    sources:\n      - src/main.s\n    linkerConfig: link.cfg\n    outputName: game\n    loadAddress: 6144\n    entrySymbol: game_start\n",
    "link.cfg": "MEMORY {\n  RAM: start=$1800, size=$6800, type=rw, file=%O;\n}\nSEGMENTS {\n  CODE: load=RAM, type=ro;\n}\n",
